#include "conv_depthwise_2d_asymmetric_input_asymmetric_kernel_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace {
inline uint32_t AlignUp32Bytes(uint32_t bytes) {
    return (bytes + 32 - 1) / 32 * 32;
}
}

namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvDepthwise2dAsymmetricInputAsymmetricKernelCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0); // [N, C, H, W]
    const gert::Shape* w_shape = context->GetInputShape(1); // [C, 1, kh, kw]

    uint32_t N  = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t C  = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t H  = static_cast<uint32_t>(x_shape->GetDim(2));
    uint32_t W  = static_cast<uint32_t>(x_shape->GetDim(3));

    // runtime attrs (order must match .Attr registrations below)
    const gert::RuntimeAttrs* attrs = context->GetAttrs();
    uint32_t kh = *(attrs->GetAttrPointer<uint32_t>(0));
    uint32_t kw = *(attrs->GetAttrPointer<uint32_t>(1));
    uint32_t sh = *(attrs->GetAttrPointer<uint32_t>(2));
    uint32_t sw = *(attrs->GetAttrPointer<uint32_t>(3));
    uint32_t ph = *(attrs->GetAttrPointer<uint32_t>(4));
    uint32_t pw = *(attrs->GetAttrPointer<uint32_t>(5));
    uint32_t dh = *(attrs->GetAttrPointer<uint32_t>(6));
    uint32_t dw = *(attrs->GetAttrPointer<uint32_t>(7));
    uint32_t has_bias = *(attrs->GetAttrPointer<uint32_t>(8));

    // compute output sizes (PyTorch conv2d convention)
    // floor((H + 2*ph - dh*(kh-1) - 1)/sh + 1)
    uint32_t Hout = (H + 2 * ph >= dh * (kh - 1) + 1)
                  ? static_cast<uint32_t>((static_cast<int64_t>(H) + 2 * ph - static_cast<int64_t>(dh) * (kh - 1) - 1) / sh + 1)
                  : 0;
    uint32_t Wout = (W + 2 * pw >= dw * (kw - 1) + 1)
                  ? static_cast<uint32_t>((static_cast<int64_t>(W) + 2 * pw - static_cast<int64_t>(dw) * (kw - 1) - 1) / sw + 1)
                  : 0;

    // Sum temporary buffer size for reducing a row (kw elements)
    uint32_t maxValue = 0;
    uint32_t minValue = 0;
    // float32 -> dtypesize=4
    AscendC::GetSumMaxMinTmpSize(kw, 4, false, maxValue, minValue);

    // inner aligned for a row (kw elements aligned to 32B)
    uint32_t innerAlignedRow = AlignUp32Bytes(kw * 4) / 4;
    // output scalar aligned to 32B for Sum dst
    uint32_t outElemAligned = 32 / 4; // float32

    // fill tiling
    tiling.set_n(N);
    tiling.set_c(C);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_kh(kh);
    tiling.set_kw(kw);
    tiling.set_sh(sh);
    tiling.set_sw(sw);
    tiling.set_ph(ph);
    tiling.set_pw(pw);
    tiling.set_dh(dh);
    tiling.set_dw(dw);
    tiling.set_has_bias(has_bias);
    tiling.set_hout(Hout);
    tiling.set_wout(Wout);
    tiling.set_sumTmpSize(minValue);
    tiling.set_innerAlignedRow(innerAlignedRow);
    tiling.set_outElemAligned(outElemAligned);

    // set block dim
    context->SetBlockDim(BLOCK_DIM);

    // save tiling buffer
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // workspace
    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}

} // namespace optiling


