python_bind_src="""
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline int64_t conv_out_size(int64_t in, int64_t pad, int64_t dilation, int64_t k, int64_t stride) {
    return (in + 2 * pad - dilation * (k - 1) - 1) / stride + 1;
}

at::Tensor conv_depthwise_2d_asymmetric_input_asymmetric_kernel_custom_impl_npu(
    const at::Tensor& x,
    const at::Tensor& w,
    c10::optional<at::Tensor> b_opt,
    int64_t kh, int64_t kw,
    int64_t sh, int64_t sw,
    int64_t ph, int64_t pw,
    int64_t dh, int64_t dw)
{
    TORCH_CHECK(x.dim() == 4, "x must be 4D NCHW");
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    TORCH_CHECK(w.dim() == 4, "w must be 4D [C,1,kh,kw]");
    TORCH_CHECK(w.size(0) == C && w.size(1) == 1 && w.size(2) == kh && w.size(3) == kw, "weight shape mismatch");

    auto Hout = conv_out_size(H, ph, dh, kh, sh);
    auto Wout = conv_out_size(W, pw, dw, kw, sw);

    auto options = x.options();
    at::Tensor y = at::empty({N, C, Hout, Wout}, options);

    int64_t has_bias = (b_opt.has_value() && b_opt.value().defined()) ? 1 : 0;
    at::Tensor b = has_bias ? b_opt.value() : at::empty({0}, options);

    // attrs: kh, kw, sh, sw, ph, pw, dh, dw, has_bias
    EXEC_NPU_CMD(aclnnConvDepthwise2dAsymmetricInputAsymmetricKernelCustom,
                 x, w, b,
                 (uint32_t)kh, (uint32_t)kw, (uint32_t)sh, (uint32_t)sw,
                 (uint32_t)ph, (uint32_t)pw, (uint32_t)dh, (uint32_t)dw, (uint32_t)has_bias,
                 y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
